result = await mcp.call_tool("tools", "ox-bridge-write", {"path": "roman.py", "content": """"Strict Roman numeral codec for the textbook-publishing pipeline.

to_roman(n)   -- encode 1..3999 in standard subtractive notation.
from_roman(s) -- decode STRICTLY; anything that is not exactly the canonical
                 form raises ValueError (lowercase, 'IIII', 'VX', 'IC', 'XM',
                 repeated subtractives like 'IXIX', >3 repeats, etc.).
"""

import re
import string

import pytest

# (value, symbol) pairs in descending order; includes subtractive pairs.
_PAIRS = [
    (1000, "M"), (900, "CM"), (500, "D"), (400, "CD"),
    (100, "C"), (90, "XC"), (50, "L"), (40, "XL"),
    (10, "X"), (9, "IX"), (5, "V"), (4, "IV"), (1, "I"),
]

_ROMAN_CHARS = frozenset(string.ascii_uppercase & set("IVXLCDM"))
_TOKEN_RE = re.compile(r"M|CM|CD|D|XC|XL|C|IX|IV|X|V|I")


def to_roman(n: int) -> str:
    """Encode an integer 1..3999 as a canonical Roman numeral."""
    if not isinstance(n, int) or isinstance(n, bool):
        raise ValueError(f"not an integer: {n!r}")
    if not 1 <= n <= 3999:
        raise ValueError(f"out of range 1..3999: {n}")
    out = []
    for value, symbol in _PAIRS:
        count, n = divmod(n, value)
        out.append(symbol * count)
    return "".join(out)


def from_roman(s: str) -> int:
    """Parse a strictly canonical Roman numeral.

    Raises ValueError unless s is exactly the canonical encoding of some
    number in 1..3999.
    """
    if not isinstance(s, str):
        raise ValueError(f"not a string: {s!r}")
    # Reject lowercase / foreign characters outright.
    if not s or any(ch not in _ROMAN_CHARS for ch in s):
        raise ValueError(f"invalid Roman numeral: {s!r}")
    # Tokenize with the canonical grammar only; any leftover means the
    # string is not composed of valid canonical tokens (e.g. 'IIII' has no
    # token boundary problem but fails the round-trip check below; 'VX',
    # 'IC', 'XM', 'IXIX' fail either here or there).
    pos = 0
    tokens = []
    while pos < len(s):
        m = _TOKEN_RE.match(s, pos)
        if m is None:
            raise ValueError(f"invalid Roman numeral: {s!r}")
        tokens.append(m.group())
        pos = m.end()
    # Strictness by construction: canonical re-encoding must match input.
    total = sum(
        {"M": 1000, "CM": 900, "D": 500, "CD": 400, "C": 100, "XC": 90,
         "L": 50, "XL": 40, "X": 10, "IX": 9, "V": 5, "IV": 4, "I": 1}[t]
        for t in tokens
    )
    canonical = to_roman(total)
    if canonical != s:
        raise ValueError(f"non-canonical Roman numeral: {s!r}")
    return total


# ---------------------------------------------------------------------------
# Tests
# ---------------------------------------------------------------------------


class TestToRoman:
    @pytest.mark.parametrize("n,expected", [
        (4, "IV"),
        (9, "IX"),
        (14, "XIV"),
        (40, "XL"),
        (90, "XC"),
        (400, "CD"),
        (900, "CM"),
        (1994, "MCMXCIV"),
        (3999, "MMMCMXCIX"),
    ])
    def test_unit_table(self, n, expected):
        assert to_roman(n) == expected

    @pytest.mark.parametrize("n", [0, 4000, -1])
    def test_out_of_range_raises(self, n):
        with pytest.raises(ValueError):
            to_roman(n)


class TestFromRomanStrict:
    def test_lowercase_rejected(self):
        with pytest.raises(ValueError):
            from_roman("mcmxciv")
        with pytest.raises(ValueError):
            from_roman("Mcmxciv")

    def test_four_repeats_rejected(self):
        with pytest.raises(ValueError):
            from_roman("IIII")

    @pytest.mark.parametrize("bad", ["IIII", "VV", "XXXX", "LLLL", "CCCC", "DDDD"])
    def test_more_than_three_or_illegal_repeats(self, bad):
        with pytest.raises(ValueError):
            from_roman(bad)

    @pytest.mark.parametrize("bad", ["VX", "IC", "XM", "IL", "XD", "LC", "DM"])
    def test_invalid_subtractive_pairs(self, bad):
        with pytest.raises(ValueError):
            from_roman(bad)

    def test_repeated_subtractive_rejected(self):
        with pytest.raises(ValueError):
            from_roman("IXIX")

    def test_non_canonical_order(self):
        with pytest.raises(ValueError):
            from_roman("XMVI")   # would be 1006-ish slop; canonical is MXCVI... rejected
        with pytest.raises(ValueError):
            from_roman("IVI")    # junk

    def test_empty_and_garbage(self):
        for bad in ["", "ABC", "M CM", "IIB"]:
            with pytest.raises(ValueError):
                from_roman(bad)

    def test_valid_roundtrip_samples(self):
        for n, expected in [(4, "IV"), (9, "IX"), (1994, "MCMXCIV")]:
            assert from_roman(expected) == n


class TestProperties:
    def test_roundtrip_all_1_to_3999(self):
        for n in range(1, 4000):
            r = to_roman(n)
            assert from_roman(r) == n

    def test_alphabet_restricted(self):
        allowed = set("IVXLCDM")
        for n in range(1, 4000):
            assert set(to_roman(n)) <= allowed


if __name__ == "__main__":
    raise SystemExit(pytest.main([__file__, "-q"]))
